package dev.arabicgames.phone;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
public final class LocalModelsActivity extends Activity {
 private Spinner choices;private TextView status;private final Handler ui=new Handler(Looper.getMainLooper());private String importing;
 private final String[] models={"quickmt-en-ar","jisr-msa","jisr-saudi"};
 private final Runnable refresh=new Runnable(){public void run(){String model=models[choices.getSelectedItemPosition()];status.setText((LocalModels.runtime()?"محرك التشغيل متاح":"محرك التشغيل غير متاح في هذه النسخة")+"\n"+(LocalModels.installed(LocalModelsActivity.this,model)?"✓ الحزمة محفوظة على الجوال":"الحزمة تحتاج تنزيلًا")+"\n"+LocalModelDownloadService.message);ui.postDelayed(this,600);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=Ui.column(this);root.setPadding(20,20,20,20);root.setBackgroundColor(Ui.BG);root.addView(Ui.text(this,"نماذج تعمل على الجوال",26));root.addView(Ui.text(this,"بعد التنزيل تعمل الترجمة بدون كمبيوتر وبدون API. QuickMT نحو 363 MB؛ جسر نحو 55 MB للتنزيل. الفصحى والسعودي يستخدمان حزمة جسر نفسها. سرعة وجودة كل نموذج تختلف؛ قارن الحوار نفسه من سجل الترجمة.",16));
  choices=new Spinner(this);choices.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"QuickMT · إنجليزي ← عربي","جسر · فصحى · INT8","جسر · سعودي · INT8"}));root.addView(choices);String selected=LocalModels.selected(this);for(int i=0;i<models.length;i++)if(models[i].equals(selected))choices.setSelection(i);
  Ui.button(this,root,"التحكم بالتأخير وسرعة القراءة المحلية",false,()->startActivity(new android.content.Intent(this,TimingActivity.class)));
  Ui.button(this,root,"تنزيل / استئناف الحزمة المختارة",true,()->startDownload(models[choices.getSelectedItemPosition()],null));
  Ui.button(this,root,"استيراد حزمة ZIP مطابقة من ملف",false,()->{importing=models[choices.getSelectedItemPosition()];Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(pick,42);}catch(ActivityNotFoundException e){LocalModelDownloadService.message="لا يوجد تطبيق لاختيار الملفات.";}});
  Ui.button(this,root,"استخدام النموذج المختار",true,()->{String model=models[choices.getSelectedItemPosition()];if(!LocalModels.runtime()||!LocalModels.installed(this,model)){LocalModelDownloadService.message="نزّل النموذج وتحقق من توفر المحرك أولًا.";return;}try{AiPreferences.save(this,AiPreferences.NATIVE,model,AiPreferences.game(this),"",false);CaptureService.translationChanged();Status.message="تم اختيار "+model+" على الجوال.";finish();}catch(Exception e){LocalModelDownloadService.message="تعذر حفظ اختيار النموذج.";}});
  status=Ui.text(this,"",16);root.addView(status);root.addView(Ui.text(this,"المصادر: QuickMT (CC-BY-4.0)، جسر (Apache-2.0)، ومحرك CTranslate2 من تنفيذ Hearth. نتحقق من SHA-256 قبل تفعيل كل حزمة. لا تستورد APK أو ملفات تشغيل ضمن حزمة النموذج.",13));Ui.button(this,root,"رجوع",false,this::finish);ScrollView scroll=new ScrollView(this);scroll.addView(root);PhoneInsets.fit(scroll);setContentView(scroll);}
 private void startDownload(String model,android.net.Uri uri){if(LocalModelDownloadService.running)return;Intent intent=new Intent(this,LocalModelDownloadService.class).putExtra("model",model);if(uri!=null)intent.setData(uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startForegroundService(intent);}catch(RuntimeException e){LocalModelDownloadService.message="تعذر بدء التنزيل؛ أعد فتح صفحة النماذج وحاول.";}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&result==RESULT_OK&&data!=null&&data.getData()!=null)startDownload(importing,data.getData());}
 @Override protected void onResume(){super.onResume();ui.post(refresh);}
 @Override protected void onPause(){ui.removeCallbacks(refresh);super.onPause();}
}
